        [ "International transfers", "Where a provider processes data outside the European Economic Area, we apply appropriate safeguards such as the European Commission's standard contractual clauses and assess risk case by case." ],
        [ "Your rights", "You may exercise access, rectification, erasure, objection, restriction and portability by writing to {{dpo_email}}. You may also withdraw consent and lodge a complaint with the Spanish Data Protection Agency (AEPD), www.aepd.es." ],
        [ "Security", "We apply reasonable technical and organisational measures: encryption in transit, access controls, audit logging and data minimisation. No system is completely infallible, but we will notify relevant incidents in accordance with the GDPR." ]
      ]
    ),
    "cookies" => LegalSeed.page(
      "Cookie policy",
      "We use cookies and similar technologies to run the site, remember your preferences and, with your consent, analyse usage and show relevant content under article 22.2 of the LSSI-CE.",
      [
        [ "What cookies are", "Cookies are small files stored on your device when you visit a website. They may be first-party or third-party, session or persistent." ],
        [ "Strictly necessary cookies", "These allow sign-in, cart persistence, language selection, form security and your cookie preferences. They do not require consent because they are essential to provide the service." ],
        [ "Analytics cookies", "These help us understand which pages are visited and how the platform is used, in aggregate. They are only enabled if you accept this category." ],
        [ "Marketing cookies", "These help measure campaigns and show more relevant content or ads. They are only enabled with your express consent." ],
        [ "Cookie table", "<table><thead><tr><th>Category</th><th>Purpose</th><th>Duration</th><th>Consent</th></tr></thead><tbody><tr><td>Necessary</td><td>Session, security, cart, language and preferences</td><td>Up to 12 months</td><td>No</td></tr><tr><td>Analytics</td><td>Aggregate usage measurement</td><td>Up to 24 months</td><td>Yes</td></tr><tr><td>Marketing</td><td>Campaign measurement and personalisation</td><td>Up to 24 months</td><td>Yes</td></tr></tbody></table>" ],
        [ "Changing your preferences", "You can accept, reject or configure cookies from the initial banner or with the \"Change cookie preferences\" button on this page at any time. You can also delete cookies in your browser settings; some features may stop working." ],
        [ "Updates", "If we change categories or providers, we will update this policy and ask for your consent again where required." ]
      ]
    ),
    "returns" => LegalSeed.page(
      "Returns and right of withdrawal",
      "This page summarises your return and withdrawal rights under Spanish consumer law (TRLGDCU) and PCMarket's buyer protection terms.",
      [
        [ "Buying from professional sellers", "If you buy from a professional seller, you have a 14-calendar-day right of withdrawal from receipt, without giving a reason. Notify the seller in writing through the platform or by email and return the item within 14 days of that notice." ],
        [ "Exceptions", "There is no withdrawal right, among others, for sealed products that have been unsealed and are not suitable for return for hygiene or data protection reasons, or for goods made to the consumer's specifications." ],
        [ "Model withdrawal form", "<p>You may use this model:</p><blockquote><p>To [seller], with address at [address]. I hereby give notice that I withdraw from my contract of sale for the following goods: [description], ordered on [date] and received on [date]. Consumer name: [name]. Address: [address]. Date: [date]. Signature (only if sent on paper).</p></blockquote>" ],
        [ "Buying from private sellers", "Between private individuals there is no statutory right of withdrawal unless the seller offers one in the listing. PCMarket buyer protection still covers the situations described in the buyer protection policy." ],
        [ "Legal guarantee", "New goods bought from professionals carry a 3-year legal guarantee of conformity from delivery. For used goods, the parties may agree a guarantee period of no less than 1 year. The guarantee covers lack of conformity existing at delivery." ],
        [ "Starting a return", "Open the order, choose \"Return or issue\" and explain the reason. If you cannot agree with the seller, open a dispute within the inspection window. Keep the packaging and proof of postage." ],
        [ "Refunds", "Refunds are made to the original payment method once the item is received or the return is evidenced, within the applicable legal periods." ]
      ]
    ),
    "buyer_protection" => LegalSeed.page(
      "Buyer protection",
      "PCMarket buyer protection is designed to make second-hand technology purchases safer. These are the main rules.",
      [
        [ "What is covered", [
          "Payments made entirely inside PCMarket.",
          "Orders that do not arrive or arrive seriously damaged.",
          "Items that materially differ from the listing description.",
          "Counterfeit items or undisclosed defects.",
          "Issues reported within the inspection window."
        ] ],
        [ "What is not covered", [
          "Payments made outside the platform, including direct transfers or other off-platform methods.",
          "Damage caused by misuse after receipt.",
          "Disagreements about taste, size or expectations not included in the description.",
          "Transactions that breach these terms or the law."
        ] ],
        [ "How the inspection window works", "Once the order is marked delivered, you have a configurable window (usually 2 days) to inspect the item and confirm receipt or open a dispute. If you do nothing, the order completes automatically and the seller is paid." ],
        [ "Opening a dispute", "Open the order, select \"Open dispute\", choose a reason and attach photos and a clear description. The seller can respond. If you cannot agree, our team reviews the evidence and may order a full or partial refund." ],
        [ "Timing", "Disputes are reviewed in order of arrival. Refunds are processed once the issue is verified and may take several business days to appear depending on your bank." ],
        [ "Contact", "If you have questions before buying, email {{support_email}} or visit the help centre." ]
      ]
    ),
    "seller_terms" => LegalSeed.page(
      "Seller terms",
      "These terms apply to anyone who lists items or sells through PCMarket, whether as a private individual or a professional seller.",
      [
        [ "General obligations", [
          "Publish accurate, complete and up-to-date information about the item, its condition and price.",
          "Have the right to sell the item and ensure it is lawful.",
          "Respond to messages and ship orders within the stated time.",
          "Pack items properly and provide tracking where the shipment allows it.",
          "Comply with applicable tax, consumer and data protection rules."
        ] ],
        [ "Private and professional sellers", "You must state whether you sell as a private individual or a professional. Professional sellers must provide their company name, tax ID and contact details, give the required pre-contractual information and honour statutory guarantees. Private sellers may not present themselves as a business or issue invoices that do not belong to them." ],
        [ "Prohibited practices", [
          "Listing stolen, counterfeit or recalled items.",
          "Manipulating photos, descriptions or reviews to mislead.",
          "Requesting off-platform payments to bypass buyer protection.",
          "Creating duplicate accounts to evade suspensions.",
          "Selling buyer personal data or using it for unrelated purposes."
        ] ],
        [ "Fees and payments", "Use of the platform is currently free, apart from optional featured services. We may introduce commissions with at least 30 days' notice. Funds are released after receipt is confirmed or the inspection window ends, less any applicable commission and agreed shipping costs." ],
        [ "DAC7 and tax information", "As a digital platform, PCMarket must collect and verify certain seller tax data and report sellers who exceed 30 sales or EUR 2,000 in a calendar year to the Spanish Tax Agency (AEAT) under model 238. If you do not provide the required data, we may limit your ability to sell." ],
        [ "Suspension", "We may suspend or close accounts that breach these terms, accumulate serious issues or fail legal obligations. Amounts owed for confirmed orders will be settled in accordance with these terms and the law." ]
      ]
    ),
    "prohibited_items" => LegalSeed.page(
      "Prohibited items",
      "To protect the community and comply with the law, certain items may not be listed on PCMarket. This list is indicative, not exhaustive.",
      [
        [ "Stolen or unlawfully obtained items", "You may not sell stolen, embezzled or fraudulently obtained items, or items whose origin you cannot prove. If we have reasonable grounds, we will remove the listing and may report it to the authorities." ],
        [ "Counterfeits and replicas", "Counterfeit products, replicas presented as genuine and any item infringing intellectual or industrial property rights are prohibited." ],
        [ "Recalled or unsafe items", "You may not sell products subject to official recalls, safety alerts or that fail applicable safety rules." ],
        [ "Locked devices", "Phones, tablets, computers and other devices with locked accounts, remote activation, iCloud, Google or corporate accounts that prevent normal use are not accepted. Sellers must unlink all accounts before shipping." ],
        [ "Weapons and regulated items", "Firearms, ammunition, prohibited knives, explosives, fireworks, tear gas and any other regulated item requiring authorisation are prohibited." ],
        [ "Dangerous or illegal products", "Drugs, medicines, hazardous chemicals, radioactive materials, human organs, protected species, identity documents, third-party personal data and malicious software are not allowed." ],
        [ "Services and content", "Illegal services, adult content, gambling, abusive lending, cryptocurrencies and pyramid schemes are not allowed." ],
        [ "Consequences", "We may remove the listing, suspend the account and, where appropriate, report it to the authorities. If you are unsure about an item, contact us at {{support_email}} before listing it." ]
      ]
    ),
    "dsa_contact" => LegalSeed.page(
      "DSA contact and illegal content notices",
      "PCMarket complies with Regulation (EU) 2022/2065 on Digital Services (DSA). This page explains how to contact us and how to report allegedly illegal content.",
      [
        [ "Point of contact", "The single point of contact for authorities, users and third parties is {{legal_email}}. For consumer and support matters, use {{support_email}}. We will reply in the language of the communication or, where not possible, in Spanish or English." ],
        [ "Reporting illegal content", "Anyone may report a listing, message or profile they consider illegal. Include the content link or identifier, the reason, sufficient explanation and, where possible, evidence. Manifestly unfounded or abusive notices may be dismissed." ],
        [ "Handling", "We will review the notice without undue delay, take proportionate measures and inform you of the decision. If we remove content, we will give the affected user a clear statement of reasons and an opportunity to appeal." ],
        [ "Internal complaints", "Users may challenge moderation, suspension or removal decisions through the contact form or by writing to {{legal_email}}. A free internal complaint system is available for at least six months from the decision." ],
        [ "Out-of-court resolution", "You may use accredited alternative dispute resolution bodies. In Spain, consumers can use the relevant Junta Arbitral de Consumo (consumer arbitration board). The EU online dispute resolution platform was discontinued in July 2025." ],
        [ "Transparency", "We publish aggregated information about moderation and notices where required by law. Relevant automated decisions are reviewed by people where they affect user rights." ],
        [ "Postal contact", "{{company_legal_name}}, {{company_address}}. For formal notices, mark the subject \"DSA\"." ]
      ]
    )
  }
}.freeze
